    private void btnProdBorrarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnProdBorrarActionPerformed
        if (prod != null) {
            if (txtProdBorrar.getText().isBlank()) {
                JOptionPane.showMessageDialog(this, "Ingresa el id del producto");
            } else {
                try {
                    adminDaoProd.borrar(prod.getIdProducto());
                } catch (Exception e) {
                    JOptionPane.showMessageDialog(this, "Error de SQL: " + e.getMessage());
                }

                try {
                    adminDaoProd.borrar(prod.getIdProducto());
                    txtProdBorrar.setText(null);
                    cbProdBorrar.setSelectedItem("Selecciona");
                    txaProdBorrar.setText(null);
                    JOptionPane.showMessageDialog(this, "Producto Borrado");
                } catch (Exception e) {
                    JOptionPane.showMessageDialog(this, "Error de SQL: " + e.getMessage());
                }

            }
        } else {
            JOptionPane.showMessageDialog(this, "No se encontró el producto");
        }
    }//GEN-LAST:event_btnProdBorrarActionPerformed

    private void btnBuscarProdBorrarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnBuscarProdBorrarActionPerformed
        if (txtProdBorrar.getText().isBlank()) {
            JOptionPane.showMessageDialog(this, "Ingresa el id del producto");
        } else {
            int id = Integer.parseInt(txtProdBorrar.getText());

            try {
                prod = adminDaoProd.seleccionarId(id);
            } catch (Exception e) {
                JOptionPane.showMessageDialog(this, "Error de SQL: " + e.getMessage());
            }

            if (prod == null) {
                JOptionPane.showMessageDialog(this, "No se encontró el producto con id: " + id);
            } else {
                //mostrar en txa
                txaProdBorrar.setText(prod.toString());

            }
        }
    }//GEN-LAST:event_btnBuscarProdBorrarActionPerformed

    private void btnGuardarClienteActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnGuardarClienteActionPerformed
//GUARDAR CLIENTES EN LA BASE DE DATOS
        if (txtNombreCliente.getText().isBlank()) {
            JOptionPane.showMessageDialog(this, "El campo nombre no puede estar vacio");
        } else if (txtApellidoCliente.getText().isBlank()) {
            JOptionPane.showMessageDialog(this, "El campo ciudad no puede estar vacío");
        } else if (txtApellidoCliente.getText().isBlank()) {
            JOptionPane.showMessageDialog(this, "El campo ciudad no puede estar vacío");
        } else if (txtTelefonoCliente.getText().isBlank()) {
            JOptionPane.showMessageDialog(this, "El campo colonia no puede estar vacío");
        } else if (lblImagenCliente.getIcon() == null) {
            JOptionPane.showMessageDialog(this, "Debes agregar una imagen");
        } else {
            cliente = new Cliente();
            cliente.setNombre(txtNombreCliente.getText());
            cliente.setApellido(txtApellidoCliente.getText());
            cliente.setCorreo(txtCorreoCliente.getText());
            cliente.setTelefono(txtTelefonoCliente.getText());
            String estadoSeleccionado = cbEstadoCliente.getSelectedItem().toString();
            cliente.setEstado(estadoSeleccionado);

            try {
                FileInputStream entradaCliente = new FileInputStream(imgCliente);
                byte[] imagenbytes = new byte[(int) imgCliente.length()];
                entradaCliente.read(imagenbytes);
                entradaCliente.close();
                cliente.setImagen(imagenbytes);
            } catch (FileNotFoundException ex) {
                Logger.getLogger(AdminMDI.class.getName()).log(Level.SEVERE, null, ex);
                JOptionPane.showMessageDialog(this, "Error al subir imagen: " + ex.getMessage());
            } catch (IOException ex) {
                Logger.getLogger(AdminMDI.class.getName()).log(Level.SEVERE, null, ex);
                JOptionPane.showMessageDialog(this, "Error al subir imagen: " + ex.getMessage());
            }

            try {
                adminDaoCliente.insertar(cliente);
                JOptionPane.showMessageDialog(this, "Guardado");
                txtNombreCliente.setText(null);
                txtApellidoCliente.setText(null);
                txtTelefonoCliente.setText(null);
                txtCorreoCliente.setText(null);
                lblImagenCliente.setIcon(null);
                cbEstadoCliente.setSelectedItem("ACTIVO");
            } catch (Exception e) {
                JOptionPane.showMessageDialog(this, "Error de SQL: " + e.getMessage());
            }
        }
    }//GEN-LAST:event_btnGuardarClienteActionPerformed

